        public static int LengthOfLongestSubstring(string s)
        {
            if (s.Length < 1)
            {
                return 0;
            }
            if (s.Length < 2)
            {
                return 1;
            }
            if (s.Length < 3)
            {
                if (s[0] != s[1])
                {
                    return 2;
                }
            }
            List<HashSet<char>> list_ofHashset = new();
            byte highestStreak = 0;
            for (int i = 0; i < s.Length; i++)
            {
                char item = s[i];
                if (highestStreak <= s.Length - i)
                    list_ofHashset.Add(new());
                for (int a = list_ofHashset.Count - 1; a >= 0; a--)
                {
                    if (list_ofHashset[a].Add(item))
                    {
                        if (list_ofHashset[a].Count > highestStreak)
                            highestStreak = (byte)list_ofHashset[a].Count;
                    }
                    else
                    {
                        list_ofHashset.RemoveAt(a);
                    }
                }
            }
            return highestStreak;
        }
        public static int LengthOfLongestSubstring_Slow(string s)
        {
            if (s.Length < 1)
            {
                return 0;
            }
            if (s.Length < 2)
            {
                return 1;
            }
            if (s.Length < 3)
            {
                if (s[0] != s[1])
                {
                    return 2;
                }
            }
            HashSet<char> hash = new();
            byte streak = 0;
            byte highestStreak = 0;
            for (int i = 0; i < s.Length; i++)
            {
                if (streak > highestStreak)
                {
                    highestStreak = streak;
                }
                hash.Clear();
                streak = 0;
                if (highestStreak > s.Length - i)
                {
                    break;
                }
                for (int j = i; j < s.Length; j++)
                {
                    char item = s[j];
                    if (hash.Add(item))
                    {
                        streak++;
                    }
                    else
                    {
                        hash.Clear();
                        if (streak > highestStreak)
                        {
                            highestStreak = streak;
                        }
                        streak = 0;
                        j--;
                    }
                }
            }
            if (streak > highestStreak)
            {
                hash = null;
                return streak;
            }
            return highestStreak;
        }
